@props(['tasks', 'selected' => []])
@php $chosen = array_map('strval', old('related_task_ids', session()->hasOldInput() ? [] : $selected) ?? []); @endphp
<section class="related-picker" data-related-picker><h3>関連タスク <small>任意・複数選択</small></h3><p>関連するタスクを選択すると、相手のタスクにもこのタスクが表示されます。</p>
    <label class="sr-only" for="related-search">関連タスクを検索</label><input type="search" id="related-search" placeholder="タスク名・番号・フェーズで検索" data-related-search>
    <p data-related-count role="status"></p><div class="related-options">
    @forelse($tasks as $option)
        <label data-related-option><input type="checkbox" name="related_task_ids[]" value="{{ $option->id }}" @checked(in_array((string)$option->id, $chosen, true))><span><small>#{{ $option->id }} · {{ \App\Models\IntermediateTask::phaseLabels()[$option->phase] ?? $option->phase }}</small><strong>{{ $option->title }}</strong></span><em>{{ ['assigned'=>'担当中','completed'=>'完了','incomplete'=>'未対応'][$option->status] ?? $option->status }}</em></label>
    @empty<p>関連付けできるタスクはまだありません。</p>@endforelse
    </div><p data-related-empty hidden>検索条件に一致するタスクはありません。</p>
</section>
<style>.related-picker{margin-top:24px;padding:22px;background:#fafcfb;border:1px solid #e2ebe6;border-radius:16px}.related-picker h3{font-size:14px;font-weight:700;color:#5c7568}.related-picker h3 small{font-size:10px;margin-left:8px;color:#9aa99f;font-weight:400}.related-picker>p{font-size:12px;line-height:1.9;color:#91a196;margin:8px 0 12px}.related-picker>input{width:100%;font-size:13px;border:1px solid #dde7e0;border-radius:11px;padding:12px;background:white;color:#5e7768}.related-options{max-height:300px;overflow-y:auto;overscroll-behavior:contain}.related-options>label{display:flex;align-items:center;gap:12px;padding:14px 10px!important;border-bottom:1px solid #edf2ee;font-size:12px;cursor:pointer;margin:0!important}.related-options>label[hidden]{display:none}.related-options>label:has(input:checked){background:#edf5ef;border-radius:10px}.related-options input{width:17px!important;height:17px;flex-shrink:0;accent-color:#6c9b80}.related-options span{min-width:0;flex:1}.related-options small{display:block;color:#9aac9e;font-size:10px}.related-options strong{display:block;overflow-wrap:anywhere;color:#698573;font-size:12px;font-weight:500;margin-top:4px}.related-options em{font-size:10px;font-style:normal;color:#9caf9f;white-space:nowrap}.related-picker input:focus-visible{outline:2px solid #9fbeaa;outline-offset:2px}</style>
<script>
document.querySelectorAll('[data-related-picker]').forEach(picker=>{const search=picker.querySelector('[data-related-search]'),options=[...picker.querySelectorAll('[data-related-option]')];const update=()=>{const term=search.value.trim().toLocaleLowerCase();options.forEach(option=>option.hidden=!option.textContent.toLocaleLowerCase().includes(term));picker.querySelector('[data-related-count]').textContent=options.filter(option=>option.querySelector('input').checked).length+'件選択中';picker.querySelector('[data-related-empty]').hidden=!options.length||options.some(option=>!option.hidden);};search.addEventListener('input',update);picker.addEventListener('change',update);update();});
</script>
